		String ordered = "PREFIX ex: <" + EX + ">\n"
				+ "SELECT ?s ?price WHERE { ?s a ex:Item ; ex:price ?price } ORDER BY ?price LIMIT 2";
		Explanation topK = explain(Explanation.Level.Telemetry, ordered);

